mapper.update:
UPDATE ai_mcp_connection
SET del_flag = id,
    enabled = 0,
    row_version = row_version + 1,
    update_by = #{actor},
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenant}
  AND id = #{id}
  AND row_version = #{expected}
  AND del_flag = 0

UPDATE ai_mcp_connection
SET sync_state = #{state},
    error_code = #{error},
    synced_at = CURRENT_TIMESTAMP,
    update_by = #{actor},
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenant}
  AND id = #{id}
  AND row_version = #{expected}
  AND del_flag = 0

mapper.select:
SELECT FROM ai_mcp_tool WHERE tenant_id = #{tenant} AND del_flag = 0
AND connection_id = #{connectionId}
ORDER BY connection_id, title, id LIMIT 2000

SELECT COUNT(DISTINCT agent_id)
FROM ai_agent_tool_config
WHERE tenant_id = #{tenant}
  AND tool_source = #{source}
  AND tool_key = #{key}
  AND del_flag = 0
